export type LabMediaType = "image" | "video";

export interface LabMedia {
  id: string;
  type: LabMediaType;
  src: string; // محلي public/lab أو رابط إنترنت — مع fallback تلقائي
  caption?: string;
  crop?: string;
}

export interface LabSubtype {
  id: string;
  name: string;
  desc: string;
  src: string;
}

export interface LabGuideCta {
  title: string;
  desc: string;
  cta: string;
  href: string;
}

export interface LabSection {
  slug: string;
  title: string;
  short: string;
  description: string;
  cover: string;
  priceFrom?: number | null;
  warranty?: string | null;
  duration?: string | null;
  active: boolean;
  order: number;
  features: string[];
  gallery: LabMedia[];
  videos: LabMedia[];
  subtypes?: LabSubtype[];
  guide?: LabGuideCta;
}

function img(id: string, src: string, caption: string, crop = "center"): LabMedia {
  return { id, type: "image", src, caption, crop };
}
function vid(id: string, src: string, caption: string): LabMedia {
  return { id, type: "video", src, caption };
}

const U = (id: string, w = 900) =>
  `https://images.unsplash.com/${id}?w=${w}&q=60&auto=format&fit=crop`;

